function replace(oldId, compId, chars) {
  const old = figma.getNodeById(oldId);
  const parent = old.parent;
  const idx = parent.children.indexOf(old);
  const x = old.x, y = old.y;
  const ni = figma.getNodeById(compId).createInstance();
  parent.insertChild(idx, ni);
  ni.x = x; ni.y = y;
  if (chars) ni.findOne(n => n.type === 'TEXT').characters = chars;
  const t = ni.findOne(n => n.type === 'TEXT');
  const info = chars + ' w=' + Math.round(t.width) + ' x=' + Math.round(t.x);
  old.remove();
  return {ni, info};
}

